from itertools import product,combinations,permutations
from pathlib import Path
import json

def T(r):return r*(r+1)//2

def credit(cost,count,c):return max(1,cost-c) if cost>0 and count>0 and c>0 else cost

# These mathematical cases are not native game or search regression evidence.
# Future damage is arbitrary nonnegative; future HP recovery obeys only proven total/headroom limits.
counts={'costFloors':0,'quotaBounds':0,'staggeredDoseSchedules':0,'netHpLowerBounds':0,'jointChoiceBounds':0}
for initial in product([0,9,14,18],repeat=3):
 for used_mask in range(8):
  used=[i for i in range(3) if used_mask>>i&1]
  remaining=[i for i in range(3) if i not in used]
  spent=sum(initial[i] for i in used)
  for exact in range(max(1,len(used)),4):
   needed=exact-len(used)
   for selected in combinations(remaining,needed):
    final_cost=spent+sum(initial[i] for i in selected)
    root_floor=exact*min(initial)
    branch_floor=max(root_floor,spent)
    assert root_floor<=branch_floor<=final_cost
    for c in [0,5,18,40]:
     for q in [1,5]:
      assert q*credit(root_floor,exact,c)<=q*credit(branch_floor,exact,c)<=q*credit(final_cost,exact,c)
      counts['costFloors']+=1
for r in [0,1,5,10]:
 for doses in product([0,3,5],repeat=3):
  for legal_mask in range(8):
   legal=[d for i,d in enumerate(doses) if legal_mask>>i&1]
   for allowance in range(4):
    upper=T(r+sum(sorted(legal,reverse=True)[:allowance]))
    old=T(r+sum(legal))
    assert upper<=old
    for n in range(min(allowance,len(legal))+1):
     for indices in combinations(range(len(legal)),n):
      selected=[legal[i] for i in indices]
      assert T(r+sum(selected))<=upper
      counts['quotaBounds']+=1
      for order in set(permutations(selected)):
       for ticks_between in product([0,1,3],repeat=len(order)):
        active=r;healed=0
        for dose,ticks in zip(order,ticks_between):
         for _ in range(ticks):
          healed+=active;active=max(0,active-1)
         active+=dose
        healed+=T(active)
        assert healed<=upper
        counts['staggeredDoseSchedules']+=1
for damage,recovered,headroom,bound,future_damage,q in product([0,10,40],[0,5,15],[0,5,30],[0,6,15,55],[0,5,20],[1,5]):
 optimistic=damage-(recovered+min(headroom,bound))//q
 for actual_heal in range(min(bound,headroom+future_damage)+1):
  actual=damage+future_damage-(recovered+actual_heal)//q
  assert optimistic<=actual
  counts['netHpLowerBounds']+=1
# Enumerate a complete future-use set, retaining cost/healing pairs from the SAME set.
for r,headroom,allowance in product([0,5],[5,30],[0,1,2]):
 for held in product([(0,0),(0,9),(0,18),(5,9)],repeat=3):
  options=[]
  for selected in combinations(range(3),allowance):
   h=T(r+sum(held[i][0] for i in selected));cost=sum(held[i][1] for i in selected)
   options.append((-min(headroom,h)+credit(cost,max(1,allowance),5),h,cost))
  joint=min(x[0] for x in options)
  separated=-min(headroom,max(x[1] for x in options))+credit(min(x[2] for x in options),max(1,allowance),5)
  assert separated<=joint
  for score,_,_ in options:
   assert joint<=score;counts['jointChoiceBounds']+=1
out={'status':'Passed','scope':'Exhaustive finite mathematical abstraction only; not native full-state/Fork/RNG proof, runtime acceptance or speedup.','counts':counts,'concreteQuotaExample':{'activeRegen':5,'heldDoses':[5,5],'remainingExplicitAllowance':1,'postCombatUpper':6,'oldBound':126,'quotaAwareBound':61},'requirements':['No unproved new healing or potion acquisition','Known nonnegative explicit potion costs; automatic uses excluded','Same policy and complete audited no-death-save winner','Unknown sources retain infinity','Full native state/Fork/RNG contract and performance still required before shipping']}
Path('.local/tool-tasks/state-evaluation-query-cost-20261006/proof-oracle-result.json').write_text(json.dumps(out,ensure_ascii=False,indent=2)+'\n')
print(json.dumps(out,ensure_ascii=False))
